  // ── tutorial
  'tutorial.chapter.start': ["시작 화면", "Start page"],
  'tutorial.chapter.view': ["헥사 보기", "The hex view"],
  'tutorial.chapter.structure': ["구조", "Structure"],
  'tutorial.chapter.tools': ["도구", "Tools"],
  'tutorial.chapter.data': ["데이터", "Data"],
  'tutorial.chapter.finish': ["마무리", "Finish"],
  'tutorial.welcome.title': ["MyHexaMaster", "MyHexaMaster"],
  'tutorial.welcome.text': ["어떤 크기의 파일이든, 디스크와 프로세스 메모리까지 바이트 단위로 보고 고치는 헥사 편집기입니다. 템플릿·디스어셈블러·검색·비교·체크섬·복구 도구를 함께 씁니다.", "A hex editor for files of any size, disks and process memory, byte by byte — with templates, a disassembler, search, compare, checksums and recovery."],
  'tutorial.actions.title': ["무엇을 할까요", "What to do"],
  'tutorial.actions.text': ["파일 열기, 새 파일, 디스크·프로세스 메모리 열기, 비교, 가져오기를 여기서 시작합니다. 파일을 창에 끌어 놓아도 열립니다.", "Open a file, start a new one, open a disk or process memory, compare or import from here. Dropping a file on the window opens it too."],
  'tutorial.samples.title': ["예제 파일", "Sample files"],
  'tutorial.samples.text': ["PNG·ZIP·ELF·PE·디스크 이미지·펌웨어 같은 예제로 템플릿과 도구를 바로 시험해 볼 수 있습니다.", "Samples — PNG, ZIP, ELF, PE, a disk image, firmware — let you try the templates and tools at once."],
  'tutorial.toolsCard.title': ["도구", "Tools"],
  'tutorial.toolsCard.text': ["문자열·디스어셈블러·계산기·복구·디스크·비교·템플릿·파일 도구는 툴바에도 있고, 각자 창으로 열립니다.", "Strings, disassembler, calculator, recovery, disks, compare, templates and file tools are also on the toolbar; each opens in its own window."],
  'tutorial.hexview.title': ["헥사 보기", "The hex view"],
  'tutorial.hexview.text': ["왼쪽은 오프셋, 가운데는 바이트, 오른쪽은 글자입니다. 00은 흐리게, 제어 문자·높은 값·FF는 색으로 나뉩니다. 휠과 스크롤 막대로 아무리 큰 파일도 바로 이동합니다.", "Offsets on the left, bytes in the middle, characters on the right. 00 is dim; control characters, high values and FF have colours. The wheel and scroll bar move through files of any size at once."],
  'tutorial.textcol.title': ["글자 열과 문자 집합", "Text column and character sets"],
  'tutorial.textcol.text': ["글자 열은 ASCII·Windows-1252·UTF-8·UTF-16·EUC-KR·Shift_JIS·EBCDIC 등으로 읽을 수 있습니다. 한글 한 글자는 UTF-8에서 3바이트입니다.", "The text column reads ASCII, Windows-1252, UTF-8, UTF-16, EUC-KR, Shift_JIS, EBCDIC and more. One Korean character takes three bytes in UTF-8."],
  'tutorial.editing.title': ["편집", "Editing"],
  'tutorial.editing.text': ["16진수를 치면 바로 바뀌고 바뀐 바이트는 빨갛게 보입니다. Insert 키로 끼워 넣기/덮어쓰기, Tab으로 글자 칸 입력. 실행 취소는 무제한입니다.", "Type hex digits to change bytes; changed bytes turn red. Insert switches insert / overwrite, Tab types in the text column. Undo is unlimited."],
  'tutorial.inspector.title': ["데이터 검사기", "Data inspector"],
  'tutorial.inspector.text': ["커서 위치의 바이트를 정수·실수·날짜·GUID·IP·색 등으로 읽습니다. 값을 두 번 클릭하면 고쳐 씁니다. LE/BE로 바이트 순서를 바꿉니다.", "The bytes at the caret read as integers, floats, dates, GUIDs, IPs, colours… Double-click a value to change it. LE/BE switches the byte order."],
  'tutorial.explorer.title': ["탐색기", "Explorer"],
  'tutorial.explorer.text': ["왼쪽 패널은 컴퓨터의 폴더와 열린 문서를 보여 줍니다. 파일을 두 번 클릭하면 헥사 편집기로 열립니다.", "The left panel shows the computer's folders and the open documents. Double-click a file to open it."],
  'tutorial.template.title': ["구조 (템플릿)", "Structure (templates)"],
